// Content with portions generated by generative AI platform
package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

import io.swagger.v3.core.util.Json;

public class ErrorResponsesHttpContractTest extends AbstractHttpContractTest {

    @Test
    public void unauthenticatedResponseUsesFinalAuditStatus() throws Exception {
        givenServer();
        givenNoBasicAuthentication();

        whenRequest("GET", "/system/v1/properties/kura", null);

        thenResponseMatchesContract(401);
        thenJsonErrorIsReturned(401, "Unauthorized");
        thenHeaderIsPresent("WWW-Authenticate");
    }

    @Test
    public void missingPathWithoutAcceptReturnsJson() throws Exception {
        givenServer();

        whenRequest("GET", "/missing-resource", null, "application/json", null);

        thenJsonErrorIsReturned(404, "Not Found");
    }

    @Test
    public void missingPathWithHtmlAcceptReturnsJson() throws Exception {
        givenServer();

        whenRequest("GET", "/missing-resource", null, "application/json", "text/html");

        thenJsonErrorIsReturned(404, "Not Found");
    }

    @Test
    public void unsupportedMethodPreservesAllowHeader() throws Exception {
        givenServer();

        whenRequest("DELETE", "/system/v1/properties/kura", null);

        thenJsonErrorIsReturned(405, "Method Not Allowed");
        thenHeaderIsPresent("Allow");
    }

    @Test
    public void headErrorDoesNotSendBody() throws Exception {
        givenServer();

        whenRequest("HEAD", "/missing-resource", null);

        thenBodylessErrorIsReturned();
    }

    private void thenJsonErrorIsReturned(int status, String message) throws Exception {
        assertEquals(status, this.response.statusCode());
        assertEquals("application/json", this.response.headers().firstValue("Content-Type").orElse("").split(";")[0]);
        assertEquals(message, Json.mapper().readTree(this.response.body()).path("message").asText());
    }

    private void thenHeaderIsPresent(String name) {
        assertTrue(this.response.headers().firstValue(name).isPresent());
    }

    private void thenBodylessErrorIsReturned() {
        assertEquals(404, this.response.statusCode());
        assertEquals("", this.response.body());
    }
}
